ex.pop:
const a = [1, 2];
a.pop();
// returns 2, a is [1]

ex.push:
const a = [1];
a.push(2);
// a is [1, 2], returns 2

ex.shift:
const a = [1, 2];
a.shift();
// returns 1, a is [2]

ex.splice:
const a = [1, 2, 3];
a.splice(1, 1, 9);
// a is [1, 9, 3], returns [2]

ex.unshift:
const a = [2];
a.unshift(1);
// a is [1, 2], returns 2
